def topo_order(deps):
    import heapq
    indeg = {n: len(set(d)) for n, d in deps.items()}
    users = {n: [] for n in deps}
    for n, ds in deps.items():
        for d in set(ds):
            users[d].append(n)
    h = [n for n, k in indeg.items() if k == 0]
    heapq.heapify(h)
    out = []
    while h:
        n = heapq.heappop(h)
        out.append(n)
        for u in users[n]:
            indeg[u] -= 1
            if indeg[u] == 0:
                heapq.heappush(h, u)
    if len(out) != len(deps):
        raise ValueError("cycle")
    return out
